package dev.thefoolish.generated.createasimpleworkouttrackingapps;public final class MainActivity extends AppScreen{protected void render(){int xp=store.number("workout_xp");int level=1+xp/100;body.addView(text("Training Guild",26,true));body.addView(card("Level "+level,"XP "+xp+" / "+(level*100)));body.addView(card("Strength",String.valueOf(store.number("stat_strength"))));body.addView(card("Endurance",String.valueOf(store.number("stat_endurance"))));android.widget.Button log=button("Log workout");log.setOnClickListener(v->AppNavigator.open(this,TimelineActivity.class));body.addView(log);}}